package ua.ember;
import android.Manifest;
import android.app.*;
import android.bluetooth.*;
import android.bluetooth.le.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.media.projection.MediaProjectionManager;
import android.net.Uri;
import android.os.*;
import android.webkit.*;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public final class MainActivity extends Activity {
 private WebView web;private EmberService service;private boolean bound;private BluetoothLeScanner scanner;private String exportJson,exportName;private Runnable permissionAction;private final Handler handler=new Handler(Looper.getMainLooper());
 private final ServiceConnection connection=new ServiceConnection(){public void onServiceConnected(ComponentName n,IBinder b){service=((EmberService.LocalBinder)b).service();service.attach(data->js("Ember.state",data.toString()));}public void onServiceDisconnected(ComponentName n){service=null;}};
 public void onCreate(Bundle state){super.onCreate(state);web=new WebView(this);web.setBackgroundColor(0xff080808);android.widget.FrameLayout root=new android.widget.FrameLayout(this);root.addView(web);root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(android.view.WindowInsets.Type.systemBars());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});setContentView(root);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(false);s.setAllowFileAccessFromFileURLs(false);s.setAllowUniversalAccessFromFileURLs(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest r){return !r.getUrl().toString().startsWith("file:///android_asset/");}public void onPageFinished(WebView v,String u){if(service!=null)service.attach(data->js("Ember.state",data.toString()));}});web.addJavascriptInterface(new Bridge(),"Native");web.loadUrl("file:///android_asset/index.html");bound=bindService(new Intent(this,EmberService.class),connection,BIND_AUTO_CREATE);}
 private void js(String function,String json){if(web!=null)web.evaluateJavascript(function+"("+json+")",null);}
 private void error(String text){js("Ember.error",JSONObject.quote(text==null?"Помилка":text));}
 private void bluetooth(Runnable action){List<String> list=new ArrayList<>();if(Build.VERSION.SDK_INT>=31){list.add(Manifest.permission.BLUETOOTH_SCAN);list.add(Manifest.permission.BLUETOOTH_CONNECT);}else list.add(Manifest.permission.ACCESS_FINE_LOCATION);if(Build.VERSION.SDK_INT>=33)list.add(Manifest.permission.POST_NOTIFICATIONS);List<String> missing=new ArrayList<>();for(String p:list)if(checkSelfPermission(p)!=PackageManager.PERMISSION_GRANTED)missing.add(p);if(!missing.isEmpty()){permissionAction=action;requestPermissions(missing.toArray(new String[0]),10);}else action.run();}
 public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);boolean granted=true;for(int i=0;i<permissions.length;i++)if(!permissions[i].equals(Manifest.permission.POST_NOTIFICATIONS))granted&=results[i]==PackageManager.PERMISSION_GRANTED;Runnable action=permissionAction;permissionAction=null;if(granted&&action!=null)action.run();else error("Дозвіл не надано. Відкрий дозволи Ember в налаштуваннях телефона.");}
 private final Runnable scanStop=this::stopScan;
 private void scan(){try{devices.clear();BluetoothManager manager=(BluetoothManager)getSystemService(BLUETOOTH_SERVICE);BluetoothAdapter a=manager.getAdapter();if(a==null||!a.isEnabled()){startActivity(new Intent(BluetoothAdapter.ACTION_REQUEST_ENABLE));return;}stopScan();scanner=a.getBluetoothLeScanner();js("Ember.devices","[]");scanner.startScan(null,new ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY).build(),scanCallback);handler.postDelayed(scanStop,12000);js("Ember.scanning","true");}catch(Exception e){error(e.getMessage());}}
 private final Map<String,JSONObject> devices=new LinkedHashMap<>();
 private final ScanCallback scanCallback=new ScanCallback(){public void onScanResult(int type,ScanResult result){handler.post(()->{try{BluetoothDevice device=result.getDevice();String name=result.getScanRecord()==null?null:result.getScanRecord().getDeviceName();if(name==null)name=device.getName();JSONObject row=new JSONObject().put("name",name==null?"Без назви":name).put("address",device.getAddress()).put("rssi",result.getRssi());devices.put(device.getAddress(),row);js("Ember.devices",new JSONArray(devices.values()).toString());}catch(Exception e){error(e.getMessage());}});}public void onScanFailed(int code){handler.post(()->{stopScan();error("Пошук Bluetooth: код "+code);});}};
 private void stopScan(){handler.removeCallbacks(scanStop);if(scanner!=null){try{scanner.stopScan(scanCallback);}catch(Exception ignored){}scanner=null;}if(web!=null)js("Ember.scanning","false");}
 private void capture(){if(Build.VERSION.SDK_INT<29){error("Музика телефона потребує Android 10 або новішого.");return;}if(service==null){error("Програма ще запускається.");return;}if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){permissionAction=this::capture;requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},11);return;}MediaProjectionManager m=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);startActivityForResult(m.createScreenCaptureIntent(),20);}
 public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null){if(request==20)error("Захоплення звуку скасовано.");return;}try{if(request==20){if(service!=null)service.startAudio(result,data);}else if(request==30){ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=getContentResolver().openInputStream(data.getData())){byte[] buf=new byte[4096];int count;while((count=in.read(buf))!=-1){if(bytes.size()+count>1048576)throw new IOException("Максимальний розмір — 1 MiB.");bytes.write(buf,0,count);}}String text=StandardCharsets.UTF_8.newDecoder().decode(java.nio.ByteBuffer.wrap(bytes.toByteArray())).toString();js("Ember.importText",JSONObject.quote(text));}else if(request==31){try(OutputStream out=getContentResolver().openOutputStream(data.getData(),"wt")){out.write(exportJson.getBytes(StandardCharsets.UTF_8));}error("Файл ефектів збережено.");}}catch(Exception e){error(e.getMessage());}}
 public final class Bridge {
  @JavascriptInterface public void command(String kind,String value){handler.post(()->{if(service==null){error("Програма ще запускається.");return;}if("connect".equals(kind))bluetooth(()->{stopScan();Intent foreground=new Intent(MainActivity.this,EmberService.class);startForegroundService(foreground);String hint="";JSONObject row=devices.get(value);if(row!=null)hint=row.optString("name");try{service.command(kind,new JSONObject().put("address",value).put("name",hint).toString());}catch(JSONException e){error(e.getMessage());}});else service.command(kind,value);});}
  @JavascriptInterface public void scan(){handler.post(()->bluetooth(()->{devices.clear();MainActivity.this.scan();}));}
  @JavascriptInterface public void audio(){handler.post(()->bluetooth(MainActivity.this::capture));}
  @JavascriptInterface public String load(){return getSharedPreferences("ember",0).getString("effects","[]");}
  @JavascriptInterface public void save(String json){if(json.length()>1048576)return;getSharedPreferences("ember",0).edit().putString("effects",json).apply();}
  @JavascriptInterface public void importFile(){handler.post(()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,30);});}
  @JavascriptInterface public void forgetDevice(String address){SavedDevices.forget(MainActivity.this,address);}
  @JavascriptInterface public void exportFile(String json,String name){if(json.length()>1048576){handler.post(()->error("Максимальний розмір — 1 MiB."));return;}handler.post(()->{exportJson=json;exportName=name.replaceAll("[^\\p{L}\\p{N}._-]","_");Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,exportName+".ember.json");startActivityForResult(i,31);});}
 }
 public void onDestroy(){stopScan();handler.removeCallbacksAndMessages(null);if(service!=null)service.attach(null);if(bound)unbindService(connection);web.removeJavascriptInterface("Native");web.destroy();web=null;super.onDestroy();}
}
